<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_manager');require_once __DIR__.'/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='compliance';$pageTitle='Compliance & Documentation';$errors=[];$ready=pm_table_exists($conn,'programme_compliance_documents');$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);$statuses=['outstanding'=>'Outstanding','submitted'=>'Submitted','verified'=>'Verified','rejected'=>'Rejected','expired'=>'Expired'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validate_csrf())$errors[]='Session validation failed.';elseif(!$ready)$errors[]='Import database/programme_resource_targets_compliance.sql first.';else{$pid=(int)($_POST['programme_id']??0);$cid=(int)($_POST['cohort_id']??0);$name=trim((string)($_POST['document_name']??''));$cat=trim((string)($_POST['requirement_category']??'Programme documentation'));$status=(string)($_POST['status']??'outstanding');$due=trim((string)($_POST['due_date']??''));$expiry=trim((string)($_POST['expiry_date']??''));$ref=trim((string)($_POST['evidence_reference']??''));$notes=trim((string)($_POST['notes']??''));if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Select a programme/cohort within your assigned scope.';if($name===''||mb_strlen($name)>180)$errors[]='Enter a document or requirement name.';if(!isset($statuses[$status]))$errors[]='Choose a valid document status.';foreach(['Due date'=>$due,'Expiry date'=>$expiry] as $label=>$v){if($v!==''&&(!DateTime::createFromFormat('!Y-m-d',$v)||DateTime::createFromFormat('!Y-m-d',$v)->format('Y-m-d')!==$v))$errors[]='Choose a valid '.$label.'.';}if($status==='verified'&&$ref==='')$errors[]='Add an evidence reference before marking a document verified.';if(!$errors){$cv=$cid?:null;$dv=$due?:null;$ev=$expiry?:null;$rv=$ref?:null;$s=$conn->prepare('INSERT INTO programme_compliance_documents(programme_id,cohort_id,document_name,requirement_category,status,due_date,expiry_date,evidence_reference,notes,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');if($s){$s->bind_param('iisssssssi',$pid,$cv,$name,$cat,$status,$dv,$ev,$rv,$notes,$managerId);$ok=$s->execute();$s->close();if($ok){set_flash('success','Requirement recorded','The compliance document has been saved.');safe_redirect('programme/compliance.php');}}$errors[]='The compliance record could not be saved.';}}}
$rows=[];$stats=['total'=>0,'verified'=>0,'outstanding'=>0,'expired'=>0];if($ready){$s=$conn->prepare("SELECT d.*,p.name programme_name,c.name cohort_name,CASE WHEN d.expiry_date<CURDATE() AND d.status='verified' THEN 1 ELSE 0 END expired_by_date,CASE WHEN d.due_date<CURDATE() AND d.status IN ('outstanding','rejected') THEN 1 ELSE 0 END overdue FROM programme_compliance_documents d JOIN programmes p ON p.id=d.programme_id LEFT JOIN cohorts c ON c.id=d.cohort_id WHERE p.programme_manager_id=? ORDER BY (d.expiry_date IS NOT NULL),d.expiry_date,d.due_date");if($s){$s->bind_param('i',$managerId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}foreach($rows as $r){$stats['total']++;if($r['status']==='verified'&&!(int)$r['expired_by_date'])$stats['verified']++;if(in_array($r['status'],['outstanding','rejected'],true)||(int)$r['overdue'])$stats['outstanding']++;if($r['status']==='expired'||(int)$r['expired_by_date'])$stats['expired']++;}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($pageTitle)?></title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=render_flashes()?><section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Governance &amp; assurance</span><h1>Programme Compliance &amp; Documentation</h1><p>Track required programme and cohort documents, submission progress, evidence references and expiry dates.</p></div></section><?php foreach($errors as $er):?><div class="pm-suite-alert"><?=e($er)?></div><?php endforeach;?><?php if(!$ready):?><div class="pm-suite-notice">Import <code>database/programme_resource_targets_compliance.sql</code>.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Requirements tracked</small><strong><?=$stats['total']?></strong><span>Document records</span></article><article class="pm-suite-kpi"><small>Verified and current</small><strong><?=$stats['verified']?></strong><span>Verified with no expired date</span></article><article class="pm-suite-kpi"><small>Outstanding</small><strong><?=$stats['outstanding']?></strong><span>Awaiting or requiring attention</span></article><article class="pm-suite-kpi"><small>Expired</small><strong><?=$stats['expired']?></strong><span>Expired status or expiry date passed</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Record a requirement</h2><p>Use a reference when marking a document as verified.</p></div><form method="post" class="pm-suite-form"><?=csrf_field()?><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort (optional)</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Document / requirement</label><input name="document_name" maxlength="180" required placeholder="e.g. Signed attendance register"></div><div class="pm-suite-field"><label>Category</label><input name="requirement_category" maxlength="100" value="Programme documentation"></div><div class="pm-suite-field"><label>Status</label><select name="status"><?php foreach($statuses as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach;?></select></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Submission due date</label><input type="date" name="due_date"></div><div class="pm-suite-field"><label>Expiry date (if applicable)</label><input type="date" name="expiry_date"></div></div><div class="pm-suite-field"><label>Evidence reference</label><input name="evidence_reference" maxlength="255" placeholder="Document ID, file name or repository reference"></div><div class="pm-suite-field"><label>Notes</label><textarea name="notes" rows="3"></textarea></div><button class="pm-suite-btn" <?=$ready?'':'disabled'?>>Save compliance record</button></form></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Documentation register</h2><p>Expired dates and overdue submissions are highlighted separately.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Requirement / scope</th><th>Status</th><th>Due date</th><th>Expiry</th><th>Evidence</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="pm-suite-empty">No compliance requirements have been recorded.</td></tr><?php else:foreach($rows as $r):$expired=(int)$r['expired_by_date']||$r['status']==='expired';?><tr><td><strong><?=e($r['document_name'])?></strong><span class="pm-suite-muted"><?=e($r['requirement_category'])?> · <?=e($r['programme_name'])?><?=!empty($r['cohort_name'])?' / '.e($r['cohort_name']):''?></span></td><td><span class="pm-suite-pill <?=$expired?'bad':($r['status']==='verified'?'good':($r['status']==='submitted'?'info':'warn'))?>"><?=$expired?'Expired':e($statuses[$r['status']]??$r['status'])?></span><?php if((int)$r['overdue']):?><span class="pm-suite-muted">Submission overdue</span><?php endif;?></td><td><?=!empty($r['due_date'])?e(date('d M Y',strtotime($r['due_date']))):'—'?></td><td><?=!empty($r['expiry_date'])?e(date('d M Y',strtotime($r['expiry_date']))):'—'?></td><td><?=e($r['evidence_reference']?:'Not supplied')?></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>"></script><script src="<?=url('js/original_pm_sidebar.js')?>"></script></body></html>
